from itertools import permutations
class Solution:
    def maxTotalSum(self, nums: List[int], k: int, mul: int) -> int:
        best = float('-inf')
        for perm in permutations(range(len(nums)), k):
            s = 0
            for pos, idx in enumerate(perm):
                s += nums[idx] * max(1, mul - pos)
            best = max(best, s)
        return best

