class Solution {
public:
    long long maxTotalSum(vector<int>& nums, int k, int mul) {
        int n = nums.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        long long best = LLONG_MIN;
        vector<int> perm(k);
        function<void(int, int)> gen = [&](int depth, int used) {
            if (depth == k) {
                long long s = 0;
                for (int p = 0; p < k; p++) s += (long long)nums[perm[p]] * max(1, mul - p);
                best = max(best, s);
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used >> i & 1) continue;
                perm[depth] = i;
                gen(depth + 1, used | 1 << i);
            }
        };
        gen(0, 0);
        return best;
    }
};

