class Solution {
    long best;
    public long maxTotalSum(int[] nums, int k, int mul) {
        best = Long.MIN_VALUE;
        permute(nums, new boolean[nums.length], new int[k], 0, k, mul);
        return best;
    }
    private void permute(int[] nums, boolean[] used, int[] perm, int depth, int k, int mul) {
        if (depth == k) {
            long s = 0;
            for (int p = 0; p < k; p++) s += (long) nums[perm[p]] * Math.max(1, mul - p);
            best = Math.max(best, s);
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            used[i] = true; perm[depth] = i;
            permute(nums, used, perm, depth + 1, k, mul);
            used[i] = false;
        }
    }
}

