    const perm = [];
    const gen = (used) => {
        if (perm.length === k) {
            let s = 0;
            for (let p = 0; p < k; p++) s += nums[perm[p]] * Math.max(1, mul - p);
            best = Math.max(best, s);
            return;
        }
        for (let i = 0; i < nums.length; i++) {
            if (used & (1 << i)) continue;
            perm.push(i);
            gen(used | (1 << i));
            perm.pop();
        }
    };
    gen(0);
    return best;
};

