class Solution:
    def maxTotalSum(self, nums: List[int], k: int, mul: int) -> int:
        NEG = float('-inf')
        dp = [NEG] * (k + 1)
        dp[0] = 0
        for v in sorted(nums, reverse=True):
            for j in range(k, 0, -1):
                dp[j] = max(dp[j] + v, dp[j - 1] + v * max(1, mul - j + 1))
        return dp[k]

