import java.util.*;
class Solution {
    public long maxTotalSum(int[] nums, int k, int mul) {
        int[] a = nums.clone();
        Arrays.sort(a);
        long NEG = Long.MIN_VALUE / 4;
        long[] dp = new long[k + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            long v = a[i];
            for (int j = k; j >= 1; j--)
                dp[j] = Math.max(dp[j] + v, dp[j - 1] + v * Math.max(1, mul - j + 1));
        }
        return dp[k];
    }
}

